/** Production HTTP/WebSocket ingress. TLS is terminated by the trusted edge proxy. */
public final class GatewayApplication {
    static final String TICKET_PATH="/api/v2/gateway/ws_ticket", WS_PATH="/api/v2/gateway/ws";
    static final String CORS_ALLOW_HEADERS="Authorization,Content-Type,Idempotency-Key,X-Aoo-Api-Version,X-Player-Id,X-Device-Id,X-Page-Instance-Id,X-Client-Channel,X-Client-Version,X-Idempotency-Key,X-Trace-Id";
    static final List<String> PROXY_IDENTITY_HEADERS=List.of("Authorization","Content-Type","Idempotency-Key","X-Player-Id","X-Device-Id","X-Page-Instance-Id","X-Client-Channel","X-Client-Version","X-Idempotency-Key","X-Trace-Id");
    static final AttributeKey<ConnectionIdentity> IDENTITY=AttributeKey.valueOf("gateway.identity");
    static final AttributeKey<String> CORS_ORIGIN=AttributeKey.valueOf("gateway.cors-origin");
    private GatewayApplication(){}
    public static void main(String[] args)throws Exception{
        String url=required("gateway.database.url","GATEWAY_DATABASE_URL"),user=required("gateway.database.user","GATEWAY_DATABASE_USER"),password=value("gateway.database.password","GATEWAY_DATABASE_PASSWORD","");
        int port=Integer.parseInt(value("gateway.http.port","GATEWAY_HTTP_PORT","8080"));
        Set<String> origins=Set.of(required("gateway.official.origins","GATEWAY_OFFICIAL_ORIGINS").split(","));
        boolean allowInsecureLanPreview=Boolean.parseBoolean(value("gateway.allow.insecure.lan.preview","GATEWAY_ALLOW_INSECURE_LAN_PREVIEW","false"));
        DataSource source=new DriverManagerDataSource(url,user,password);GatewayDatabaseBootstrap.verify(source);
        Clock clock=Clock.systemUTC();JdbcWsTicketService tickets=new JdbcWsTicketService(source,clock);ObjectMapper json=new ObjectMapper().findAndRegisterModules();
        var providers=ServiceLoader.load(GatewayRuntimeProvider.class).stream().toList();if(providers.size()!=1)throw new IllegalStateException("exactly one GatewayRuntimeProvider is required, found "+providers.size());GatewayRuntimeProvider.Runtime production=providers.getFirst().get().create(source,json,clock);java.util.function.Supplier<GatewayWebSocketFrameHandler.Factory> webSockets=()->production.factory(json,clock);String internalToken=required("gateway.internal.token","GATEWAY_INTERNAL_TOKEN");int internalPort=Integer.parseInt(value("gateway.internal.port","GATEWAY_INTERNAL_PORT","18080"));var internalAuthority=startInternalAuthority(internalPort,production.authority(),internalToken,json);
        HttpClient http=HttpClient.newBuilder().connectTimeout(java.time.Duration.ofSeconds(3)).build();
        URI version=URI.create(value("gateway.version.url","GATEWAY_VERSION_URL","http://127.0.0.1:8095"));
        URI account=URI.create(value("gateway.account.url","GATEWAY_ACCOUNT_URL","http://127.0.0.1:8096"));
        URI hall=URI.create(value("gateway.hall.url","GATEWAY_HALL_URL","http://127.0.0.1:8093"));
        URI social=URI.create(value("gateway.social.url","GATEWAY_SOCIAL_URL","http://127.0.0.1:8097"));
        EventLoopGroup boss=new NioEventLoopGroup(1),workers=new NioEventLoopGroup();
        ThreadPoolExecutor authorityWorkers=new ThreadPoolExecutor(8,8,0L,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(512),Thread.ofPlatform().name("gateway-authority-",0).factory(),new ThreadPoolExecutor.AbortPolicy());
        Runtime.getRuntime().addShutdownHook(new Thread(()->{internalAuthority.stop(0);production.authority().close();authorityWorkers.shutdownNow();boss.shutdownGracefully();workers.shutdownGracefully();},"gateway-shutdown"));
        new ServerBootstrap().group(boss,workers).channel(NioServerSocketChannel.class).childHandler(new ChannelInitializer<SocketChannel>(){protected void initChannel(SocketChannel ch){ch.pipeline().addLast(new HttpServerCodec(),new HttpObjectAggregator(16*1024),new Ingress(tickets,json,origins,authorityWorkers,webSockets,http,version,account,hall,social,allowInsecureLanPreview));}}).bind(port).sync().channel().closeFuture().sync();
    }

    static final class Ingress extends SimpleChannelInboundHandler<FullHttpRequest>{
        private final JdbcWsTicketService tickets;private final ObjectMapper json;private final Set<String> origins;private final Executor authorityWorkers;private final java.util.function.Supplier<GatewayWebSocketFrameHandler.Factory> webSockets;private final HttpClient http;private final URI version;private final URI account;private final URI hall;private final URI social;private final boolean allowInsecureLanPreview;
        Ingress(JdbcWsTicketService tickets,ObjectMapper json,Set<String> origins,Executor authorityWorkers,GatewayWebSocketFrameHandler.Factory webSockets){this(tickets,json,origins,authorityWorkers,()->webSockets,HttpClient.newHttpClient(),URI.create("http://127.0.0.1:8095"),URI.create("http://127.0.0.1:8096"),URI.create("http://127.0.0.1:8093"),URI.create("http://127.0.0.1:8097"),false);}
        Ingress(JdbcWsTicketService tickets,ObjectMapper json,Set<String> origins,Executor authorityWorkers,java.util.function.Supplier<GatewayWebSocketFrameHandler.Factory> webSockets,HttpClient http,URI version,URI account,URI hall,URI social){this(tickets,json,origins,authorityWorkers,webSockets,http,version,account,hall,social,false);}
        Ingress(JdbcWsTicketService tickets,ObjectMapper json,Set<String> origins,Executor authorityWorkers,java.util.function.Supplier<GatewayWebSocketFrameHandler.Factory> webSockets,HttpClient http,URI version,URI account,URI hall,URI social,boolean allowInsecureLanPreview){this.tickets=tickets;this.json=json;this.authorityWorkers=Objects.requireNonNull(authorityWorkers);this.webSockets=Objects.requireNonNull(webSockets);this.http=Objects.requireNonNull(http);this.version=Objects.requireNonNull(version);this.account=Objects.requireNonNull(account);this.hall=Objects.requireNonNull(hall);this.social=Objects.requireNonNull(social);this.allowInsecureLanPreview=allowInsecureLanPreview;this.origins=origins.stream().map(String::strip).filter(s->!s.isEmpty()).collect(java.util.stream.Collectors.toUnmodifiableSet());if(this.origins.isEmpty())throw new IllegalArgumentException("official origins required");}
        protected void channelRead0(ChannelHandlerContext ctx,FullHttpRequest req){req.retain();try{authorityWorkers.execute(()->{try{process(ctx,req);}finally{req.release();}});}catch(RejectedExecutionException saturated){req.release();send(ctx,HttpResponseStatus.SERVICE_UNAVAILABLE,HttpResult.failure(GatewayErrorCode.BACKPRESSURE,Map.of(),trace(req),time()));}}
        private void process(ChannelHandlerContext ctx,FullHttpRequest req){String trace=trace(req);try{
            QueryStringDecoder uri=new QueryStringDecoder(req.uri());if(WS_PATH.equals(uri.path()))assertNoLongToken(uri);
            if(uri.path().startsWith("/internal/")){send(ctx,HttpResponseStatus.NOT_FOUND,Map.of("code","NOT_FOUND","traceId",trace));return;}
            String requestOrigin=req.headers().get(HttpHeaderNames.ORIGIN);if(requestOrigin!=null&&origins.contains(requestOrigin))ctx.channel().attr(CORS_ORIGIN).set(requestOrigin);
            if(req.method()==HttpMethod.OPTIONS){official(req);preflight(ctx,req);return;}
            if(HttpRoutePolicy.isRetiredEntry(uri.path())){send(ctx,HttpResponseStatus.GONE,HttpResult.failure(GatewayErrorCode.LEGACY_ENTRY_DISABLED,Map.of(),trace,time()));return;}
            if(!HttpRoutePolicy.isProductionRoute(uri.path())){send(ctx,HttpResponseStatus.NOT_FOUND,HttpResult.failure(GatewayErrorCode.INVALID_ENVELOPE,Map.of(),trace,time()));return;}
            if("/api/v2/version/check".equals(uri.path())){official(req);requireTls(req);HttpRoutePolicy.requireVersion(req.headers().get(HttpRoutePolicy.API_VERSION_HEADER));proxy(ctx,req,version.resolve("/v1/version/check"),"version",true);return;}
            if(uri.path().startsWith("/api/v2/account/")){official(req);requireTls(req);HttpRoutePolicy.requireVersion(req.headers().get(HttpRoutePolicy.API_VERSION_HEADER));proxy(ctx,req,account.resolve(req.uri()),"account",false);return;}
            if(uri.path().startsWith("/api/v2/player-profile/")){official(req);requireTls(req);HttpRoutePolicy.requireVersion(req.headers().get(HttpRoutePolicy.API_VERSION_HEADER));String suffix=req.uri().substring("/api/v2/player-profile".length());proxy(ctx,req,account.resolve("/v1/player-profile"+suffix),"account",false);return;}
            if(uri.path().startsWith("/api/v2/hall/")){official(req);requireTls(req);HttpRoutePolicy.requireVersion(req.headers().get(HttpRoutePolicy.API_VERSION_HEADER));proxy(ctx,req,hall.resolve(req.uri()),"hall",false);return;}
            if(Set.of("/api/v2/social","/api/v2/notifications","/api/v2/mail","/api/v2/notices","/api/v2/red-dots").contains(uri.path())){official(req);requireTls(req);HttpRoutePolicy.requireVersion(req.headers().get(HttpRoutePolicy.API_VERSION_HEADER));proxy(ctx,req,social.resolve(req.uri().replaceFirst("^/api/v2","/v1")),"social",false);return;}
            if(TICKET_PATH.equals(uri.path())){if(req.method()!=HttpMethod.POST){send(ctx,HttpResponseStatus.METHOD_NOT_ALLOWED,HttpResult.failure(GatewayErrorCode.INVALID_ENVELOPE,Map.of(),trace,time()));return;}requireTls(req);HttpRoutePolicy.requireVersion(req.headers().get(HttpRoutePolicy.API_VERSION_HEADER));String origin=official(req);String device=header(req,"X-Device-Id"),page=header(req,"X-Page-Instance-Id"),idem=header(req,"X-Idempotency-Key"),access=bearer(req);var issued=tickets.issue(access,device,origin,page,idem);send(ctx,HttpResponseStatus.OK,HttpResult.success(Map.of("wsTicket",issued.ticket(),"expiresInSeconds",JdbcWsTicketService.TTL.toSeconds(),"wsUrl",WS_PATH),trace,time()));return;}
            if(WS_PATH.equals(uri.path())){if(req.method()!=HttpMethod.GET)throw new IllegalArgumentException("websocket upgrade requires GET");requireTls(req);String origin=official(req),ticket=single(uri,"ticket"),page=single(uri,"pageInstanceId");ConnectionIdentity identity=tickets.consume(ticket,origin,page);ctx.channel().attr(IDENTITY).set(identity);String location="wss://"+header(req,HttpHeaderNames.HOST)+WS_PATH;WebSocketServerHandshaker handshaker=new WebSocketServerHandshakerFactory(location,null,true,64*1024).newHandshaker(req);if(handshaker==null){WebSocketServerHandshakerFactory.sendUnsupportedVersionResponse(ctx.channel());return;}GatewayWebSocketFrameHandler.Factory gameFrames=webSockets.get();ctx.pipeline().addLast("gateway-v2-business",gameFrames.create(identity));handshaker.handshake(ctx.channel(),req).addListener(future->{if(future.isSuccess()){GatewaySessionRegistry.global().connected(ctx.channel(),identity,json,Clock.systemUTC());}else{GatewaySessionRegistry.global().disconnected(ctx.channel());if(ctx.pipeline().get("gateway-v2-business")!=null)ctx.pipeline().remove("gateway-v2-business");ctx.close();}});return;}
            throw new IllegalStateException("allowlisted route has no handler");
        }catch(RiskAdmissionException e){send(ctx,HttpResponseStatus.FORBIDDEN,HttpResult.failure(e.code(),Map.of(),trace,time()));}catch(GatewayTicketException e){String reason=e instanceof JdbcWsTicketService.TicketAuthorizationException rejected?" reason="+rejected.reason():"";System.err.println("gateway request rejected code="+e.code()+reason+" path="+new QueryStringDecoder(req.uri()).path()+" origin="+req.headers().get(HttpHeaderNames.ORIGIN)+" trace="+trace);send(ctx,e.code()==GatewayErrorCode.UNAUTHORIZED?HttpResponseStatus.UNAUTHORIZED:HttpResponseStatus.FORBIDDEN,HttpResult.failure(e.code(),Map.of(),trace,time()));}catch(HttpRoutePolicy.UnsupportedApiVersionException e){send(ctx,HttpResponseStatus.UPGRADE_REQUIRED,HttpResult.failure(GatewayErrorCode.API_VERSION_REQUIRED,Map.of(),trace,time()));}catch(IllegalArgumentException|SecurityException e){System.err.println("gateway request rejected reason="+e.getMessage()+" path="+new QueryStringDecoder(req.uri()).path()+" origin="+req.headers().get(HttpHeaderNames.ORIGIN)+" trace="+trace);send(ctx,HttpResponseStatus.BAD_REQUEST,HttpResult.failure(GatewayErrorCode.INVALID_ENVELOPE,Map.of(),trace,time()));}catch(RuntimeException e){System.err.println("gateway request failed type="+e.getClass().getSimpleName()+" reason="+e.getMessage()+" path="+new QueryStringDecoder(req.uri()).path()+" trace="+trace);send(ctx,HttpResponseStatus.INTERNAL_SERVER_ERROR,HttpResult.failure(GatewayErrorCode.BACKPRESSURE,Map.of(),trace,time()));}}
        private Map<String,Object> body(FullHttpRequest req){try{return json.readValue(io.netty.buffer.ByteBufUtil.getBytes(req.content()),new com.fasterxml.jackson.core.type.TypeReference<>(){});}catch(java.io.IOException e){throw new IllegalArgumentException("invalid JSON",e);}}
        private String official(FullHttpRequest req){String origin=header(req,HttpHeaderNames.ORIGIN);if(!origins.contains(origin))throw new GatewayTicketException(GatewayErrorCode.WS_TICKET_REJECTED);return origin;}
        private void requireTls(FullHttpRequest req){String proto=req.headers().get("X-Forwarded-Proto");if("https".equalsIgnoreCase(proto)||"wss".equalsIgnoreCase(proto))return;String host=Optional.ofNullable(req.headers().get(HttpHeaderNames.HOST)).orElse("").split(":",2)[0];if(host.equals("127.0.0.1")||host.equals("localhost")||host.equals("[::1]"))return;String origin=req.headers().get(HttpHeaderNames.ORIGIN);if(allowInsecureLanPreview&&origin!=null&&origins.contains(origin)&&isPrivateIpv4(host)&&URI.create(origin).getHost().equals(host))return;throw new SecurityException("trusted TLS edge required");}
        private static boolean isPrivateIpv4(String host){String[]parts=host.split("\\.");if(parts.length!=4)return false;try{int a=Integer.parseInt(parts[0]),b=Integer.parseInt(parts[1]);return a==10||(a==172&&b>=16&&b<=31)||(a==192&&b==168);}catch(NumberFormatException invalid){return false;}}
        private static void assertNoLongToken(QueryStringDecoder uri){for(String name:uri.parameters().keySet())if(!name.equals("ticket")&&!name.equals("pageInstanceId"))throw new IllegalArgumentException("credentials and extra parameters forbidden in websocket URL");}
        private static String single(QueryStringDecoder u,String n){List<String> values=u.parameters().get(n);if(values==null||values.size()!=1||values.getFirst().isBlank())throw new IllegalArgumentException("missing "+n);return values.getFirst();}
        private static String bearer(FullHttpRequest r){String v=header(r,HttpHeaderNames.AUTHORIZATION);if(!v.startsWith("Bearer ")||v.length()==7)throw new GatewayTicketException(GatewayErrorCode.UNAUTHORIZED);return v.substring(7);}
        private static String header(FullHttpRequest r,CharSequence n){String v=r.headers().get(n);if(v==null||v.isBlank())throw new IllegalArgumentException("missing header "+n);return v;}
        private static String trace(FullHttpRequest r){String v=r.headers().get("X-Trace-Id");return v==null||v.isBlank()?UUID.randomUUID().toString():v;}
        private com.aoo.bcg.gamespi.time.AuthoritativeTimeSource time(){return new com.aoo.bcg.gamespi.time.AuthoritativeTimeSource(Clock.systemUTC());}
        private void preflight(ChannelHandlerContext c,FullHttpRequest req){FullHttpResponse out=new DefaultFullHttpResponse(HttpVersion.HTTP_1_1,HttpResponseStatus.NO_CONTENT);cors(c,out);out.headers().set(HttpHeaderNames.ACCESS_CONTROL_ALLOW_METHODS,"GET,POST,PUT,OPTIONS").set(HttpHeaderNames.ACCESS_CONTROL_ALLOW_HEADERS,CORS_ALLOW_HEADERS).set(HttpHeaderNames.ACCESS_CONTROL_MAX_AGE,"600").setInt(HttpHeaderNames.CONTENT_LENGTH,0);c.writeAndFlush(out).addListener(ChannelFutureListener.CLOSE);}
        private void proxy(ChannelHandlerContext c,FullHttpRequest req,URI target,String service,boolean versionRequest){try{HttpRequest.Builder b=HttpRequest.newBuilder(target).timeout(java.time.Duration.ofSeconds(8)).method(req.method().name(),req.content().isReadable()?HttpRequest.BodyPublishers.ofByteArray(io.netty.buffer.ByteBufUtil.getBytes(req.content())):HttpRequest.BodyPublishers.noBody());for(String name:PROXY_IDENTITY_HEADERS){String value=req.headers().get(name);if(value!=null)b.header(name,value);}if(versionRequest)b.header("X-API-Version",HttpRoutePolicy.API_VERSION);else b.header(HttpRoutePolicy.API_VERSION_HEADER,HttpRoutePolicy.API_VERSION);HttpResponse<byte[]> response=http.send(b.build(),HttpResponse.BodyHandlers.ofByteArray());FullHttpResponse out=new DefaultFullHttpResponse(HttpVersion.HTTP_1_1,HttpResponseStatus.valueOf(response.statusCode()),io.netty.buffer.Unpooled.wrappedBuffer(response.body()));out.headers().set(HttpHeaderNames.CONTENT_TYPE,response.headers().firstValue("Content-Type").orElse("application/json; charset=utf-8")).setInt(HttpHeaderNames.CONTENT_LENGTH,response.body().length).set(HttpHeaderNames.CACHE_CONTROL,"no-store");cors(c,out);c.writeAndFlush(out).addListener(ChannelFutureListener.CLOSE);}catch(Exception failure){String trace=trace(req);String display=Map.of("version","版本服务","account","账号服务","hall","大厅服务","social","社交服务").getOrDefault(service,"业务服务");System.err.println("gateway upstream unavailable service="+service+" trace="+trace+" target="+target+" cause="+failure.getClass().getSimpleName()+":"+failure.getMessage());send(c,HttpResponseStatus.BAD_GATEWAY,Map.of("code","UPSTREAM_UNAVAILABLE","message",display+"暂时不可用，请稍后重试","traceId",trace,"data",Map.of("service",service)));}}
        private void cors(ChannelHandlerContext c,FullHttpResponse out){String origin=c.channel().attr(CORS_ORIGIN).get();if(origin!=null)out.headers().set(HttpHeaderNames.ACCESS_CONTROL_ALLOW_ORIGIN,origin).set(HttpHeaderNames.VARY,"Origin");}
        private void send(ChannelHandlerContext c,HttpResponseStatus status,Object body){try{byte[] bytes=json.writeValueAsBytes(body);FullHttpResponse out=new DefaultFullHttpResponse(HttpVersion.HTTP_1_1,status,io.netty.buffer.Unpooled.wrappedBuffer(bytes));out.headers().set(HttpHeaderNames.CONTENT_TYPE,"application/json; charset=utf-8").setInt(HttpHeaderNames.CONTENT_LENGTH,bytes.length).set(HttpHeaderNames.CACHE_CONTROL,"no-store");cors(c,out);c.writeAndFlush(out).addListener(ChannelFutureListener.CLOSE);}catch(Exception failure){c.close();}}
    }
        private static com.sun.net.httpserver.HttpServer startInternalAuthority(int port,GatewayRuntimeProvider.RoomAuthority authority,String token,ObjectMapper json)throws Exception{var server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress(java.net.InetAddress.getLoopbackAddress(),port),64);server.createContext("/internal/v1/session/replace",exchange->{int status=200;Object data;try{String supplied=Optional.ofNullable(exchange.getRequestHeaders().getFirst("X-Aoo-Internal-Token")).orElse("");if(!"POST".equals(exchange.getRequestMethod())||!java.security.MessageDigest.isEqual(token.getBytes(StandardCharsets.UTF_8),supplied.getBytes(StandardCharsets.UTF_8)))throw new SecurityException("internal session replacement rejected");Map<String,Object>body=json.readValue(exchange.getRequestBody(),new com.fasterxml.jackson.core.type.TypeReference<>(){});long accountId=((Number)body.get("accountId")).longValue();String sessionId=String.valueOf(body.get("sessionId"));long authGeneration=((Number)body.get("authGeneration")).longValue();if(accountId<=0||sessionId.isBlank()||authGeneration<0)throw new IllegalArgumentException("invalid session replacement");data=Map.of("closed",GatewaySessionRegistry.global().replace(accountId,sessionId,authGeneration,json,Clock.systemUTC()));}catch(SecurityException denied){status=403;data=Map.of("code","INTERNAL_SESSION_FORBIDDEN");}catch(Exception failure){status=400;data=Map.of("code","INTERNAL_SESSION_INVALID");}byte[]bytes=json.writeValueAsBytes(data);exchange.sendResponseHeaders(status,bytes.length);try(var output=exchange.getResponseBody()){output.write(bytes);}});server.createContext("/internal/v1/room-authority",exchange->{String trace=Optional.ofNullable(exchange.getRequestHeaders().getFirst("X-Trace-Id")).orElse(UUID.randomUUID().toString());int status=200;Object data;try{String supplied=Optional.ofNullable(exchange.getRequestHeaders().getFirst("X-Aoo-Internal-Token")).orElse("");if(!"POST".equals(exchange.getRequestMethod())||!java.security.MessageDigest.isEqual(token.getBytes(StandardCharsets.UTF_8),supplied.getBytes(StandardCharsets.UTF_8)))throw new SecurityException("internal authority rejected");Map<String,Object>body=json.readValue(exchange.getRequestBody(),new com.fasterxml.jackson.core.type.TypeReference<>(){});String path=exchange.getRequestURI().getPath();if(path.endsWith("/create"))data=authority.create(body);else if(path.endsWith("/recover"))data=authority.recover(body);else if(path.endsWith("/join"))data=authority.join(body);else if(path.endsWith("/remove")){authority.remove(((Number)body.get("roomId")).longValue(),((Number)body.get("fencingToken")).longValue());data=Map.of("removed",true);}else{status=404;data=Map.of("code","NOT_FOUND");}}catch(RoomAuthorityBusinessError business){status=business.status();data=Map.of("code",business.code(),"message",business.getMessage());}catch(SecurityException denied){status=403;data=Map.of("code","INTERNAL_AUTHORITY_FORBIDDEN");}catch(Exception failure){status=500;Throwable root=failure;while(root.getCause()!=null)root=root.getCause();System.err.println("room authority failed path="+exchange.getRequestURI().getPath()+" trace="+trace+" cause="+root.getClass().getSimpleName()+":"+String.valueOf(root.getMessage()));data=Map.of("code","INTERNAL_AUTHORITY_FAILED","message",failure.getClass().getSimpleName());}byte[]bytes=json.writeValueAsBytes(status==200?Map.of("code","OK","data",data,"traceId",trace):data);exchange.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");exchange.sendResponseHeaders(status,bytes.length);try(var output=exchange.getResponseBody()){output.write(bytes);}});server.setExecutor(java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor());server.start();return server;}
    private static String required(String p,String e){String v=value(p,e,null);if(v==null||v.isBlank())throw new IllegalStateException("missing "+p+" / "+e);return v;}
    private static String value(String p,String e,String fallback){String v=System.getProperty(p);if(v==null||v.isBlank())v=System.getenv(e);return v==null||v.isBlank()?fallback:v;}
}
